const holocallDialogueAnswers={disponibilidade:'Tenho disponibilidade imediata para oportunidades como <strong>Desenvolvedor Backend Júnior (C#/.NET, SQL Server, Java ou Node.js)</strong> — presencial ou híbrido em <strong>Goiânia, GO</strong>, ou <strong>100% remoto</strong>. É só me chamar no WhatsApp (62) 99842-1308 ou e-mail abaixo.',entrevista:'Perfeito, Choom! Clique em <strong>[Chamar no WhatsApp]</strong> abaixo para abrir a conversa já preenchida no <strong>(62) 99842-1308</strong> ou envie um e-mail para <strong>miqueiash989@gmail.com</strong> com os horários disponíveis.',sql_vb6:'Na <strong>Zetti</strong>, dezenas de farmácias dependem diariamente do ERP em <strong>VB6 e SQL Server</strong>. Lá eu crio e otimizo <strong>queries, views e stored procedures</strong> e entrego demandas críticas como o <strong>CNPJ Alfanumérico</strong> e novos impostos sem derrubar a produção — o que me deu uma base real de banco de dados e regras de negócio que aplico em <strong>C#/.NET</strong>.',estudando:'Estou cursando o <strong>Bacharelado em Engenharia de Software na UNIFAN (conclusão em 2027)</strong> e aprofundando diariamente em <strong>C# / .NET, Arquitetura Limpa, otimização de Stored Procedures no SQL Server e testes automatizados</strong>.'};function answerHolocallChoice(choiceKey,btnEl){playUiSound(620,1280,0.08,'triangle');for(let i=0;i<lists.wheelBtns.length;i++){lists.wheelBtns[i].classList.toggle('active',lists.wheelBtns[i]===btnEl);}
const ans=holocallDialogueAnswers[choiceKey];if(ans)setSpeech(ans);bumpDossierSync('holo_q_'+choiceKey,6);}
